    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9, 0.95],
    [80+Math.sin(t*0.45+1.5)*110, 40+Math.cos(t*0.65+2.5)*60, 0.075, 2.1, 0.88],
    [400+Math.cos(t*0.55+3)*70, 200+Math.sin(t*0.75+0.5)*50, 0.085, 1.8, 1.02],
    [200+Math.sin(t*0.38+4.5)*95, 30+Math.cos(t*0.48+1)*75, 0.06, 2.4, 0.92]
  ];
  let aS = 0, iS = 0, energy = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp), wave2 = Math.sin(d*f*1.618 - t*sp*0.785 + 0.5);
    aS += (wave + wave2*0.4) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    energy += Math.exp(-d*0.008) * (0.5 + 0.5*Math.sin(t*sp*0.3)) * w;
  }
  const n = src.length;
  aS /= n; iS /= n; energy /= n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1) + Math.sin(sx*0.05+sy*0.01-t*0.6))/3
    + Math.sin((sx+sy)*0.12+t*2.5)*0.15 + Math.sin((sx-sy)*0.1-t*2)*0.15
