  const cell = Math.tanh((cell1 + cell2*0.6 + Math.sin((sx+sy)*0.1+t)*0.4)*1.3)*0.3;
  const fine = (Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5) + Math.sin(sx*0.25-sy*0.3+t*2))*0.08;
  const rd1 = aS - iS*0.65 + bg*0.25 + spiral*0.3;
  const rd2 = Math.tanh((rd1 + energy*0.5)*2.0);
  const reaction = Math.tanh(rd2*1.8 + cell + fine);
  const blend = reaction*0.7 + cell*0.2 + fine*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,95],[12,85,125],[18,135,145],
    [60,170,130],[140,190,80],[210,195,60],
    [225,155,55],[220,100,65],[180,60,80],
    [120,30,70],[55,18,55],[5,12,52]
